code='''def transform(grid):
    # Detect connected nonzero components and encode each T by its orientation.
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); pts=[]
          while stack:
            y,x=stack.pop(); pts.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              q=(y+dy,x+dx)
              if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen: seen.add(q); stack.append(q)
          if len(pts)>=4: comps.append(pts)
    out=[[0]*6 for _ in range(3)]
    for pts in comps:
      r0=min(y for y,x in pts); r1=max(y for y,x in pts); c0=min(x for y,x in pts); c1=max(x for y,x in pts)
      # output locations are spatial bins; color indicates stem-up/down
      rr=min(2, int(((r0+r1)/2)*3/max(1,h)))
      cc=min(5, int(((c0+c1)/2)*6/max(1,w)))
      top=sum(1 for y,x in pts if y==r0); bottom=sum(1 for y,x in pts if y==r1)
      color=3 if top<bottom else 1
      out[rr][cc]=color
    return out
'''
